function useDemoStore(key, initialValue) {
  const [value, setValue] = useState(() => {
    try {
      const saved = window.localStorage.getItem(key)
      return saved ? JSON.parse(saved) : initialValue
    } catch { return initialValue }
  })
  useEffect(() => {
    try { window.localStorage.setItem(key, JSON.stringify(value)) } catch { /* La demo continúa aun sin cuota de almacenamiento. */ }
  }, [key, value])
  return [value, setValue]
}

function DemoEditor({ editor, planOptions, tenantOptions, records, onClose, onSave }) {
  const isTenant = editor.kind === 'tenant'
  const isPlan = editor.kind === 'plan'
  const isAdmin = editor.kind === 'admin'
  const initial = editor.value ? (isTenant ? { suspensionManual:false, ...editor.value } : isAdmin ? { activo:true, ...editor.value } : editor.value) : (isTenant
    ? { nombre: '', nombreCorto:'', ruc:'', contacto:'', email:'', telefono:'', codigo:'', plan: planOptions[0]?.nombre || 'Prueba gratuita', estado: 'Activo', periodoPago: 'Mensual', fechaInicio: '', fechaVencimiento: '', estadoPago: 'Al día', politicaAcceso: 'Suspender al vencer', diasGracia: 3, suspensionManual: false, admins: 1, usuariosActuales: 0, usuariosLimite: 0, ultimoAcceso: 'Nunca', riesgo: 'Normal' }
    : isPlan ? { nombre: '', clientes: 0, precioMensual: 0, maxUsuarios: 1, maxAlmacenes: 1, color: '#00c896' }
      : { tenant: tenantOptions[0]?.nombre || '', nombre: '', email: '', tipo: 'Admin Owner', activo: true })
  const [form, setForm] = useState(initial)
  const businessState = isTenant ? deriveBusinessState(form) : null
  const accessPreview = isTenant ? subscriptionAccess({ ...form, estado: businessState }) : null
  const [errors, setErrors] = useState({})
  const dialogRef = useRef(null)
  const titleId = `editor-${editor.kind}-title`
  useEffect(() => {
    const previous = document.activeElement
    dialogRef.current?.querySelector('input, select, button')?.focus()
    const handleKey = event => { if (event.key === 'Escape') onClose() }
    document.addEventListener('keydown', handleKey)
    return () => { document.removeEventListener('keydown', handleKey); previous?.focus?.() }
  }, [onClose])
  const set = (key, value) => setForm(current => ({
    ...current,
    [key]: value,
    ...(isTenant && key === 'nombre' && !editor.value && (!current.codigo || current.codigo === toTenantSlug(current.nombre)) ? { codigo:toTenantSlug(value) } : {}),
    ...(isTenant && key === 'fechaInicio' ? { fechaVencimiento: calculateSubscriptionEnd(value, current.periodoPago) } : {}),
    ...(isTenant && key === 'periodoPago' && current.fechaInicio ? { fechaVencimiento: calculateSubscriptionEnd(current.fechaInicio, value) } : {}),
  }))
  const placeholders = {
    nombre: isPlan ? 'Plan Corporativo' : isAdmin ? 'Ana Torres' : 'Empresa XYZ SAC', nombreCorto: 'XYZ SAC', ruc: '20123456789', contacto: 'José Pérez',
    email: 'contacto@empresa.com', telefono: '+51 999 888 777', codigo: 'empresa-xyz', precioMensual: '99', maxUsuarios: '10',
    maxAlmacenes: '3', diasGracia: '3',
  }
  const field = (label, key, options, type = 'text', wide = false, hint = '') => {
    const id = `editor-${editor.kind}-${key}`
    const controlClass = `rounded-lg border bg-[#0e1117] px-3 py-2.5 text-sm text-[#e8edf2] outline-none focus:ring-2 focus:ring-[#00c896]/40 ${errors[key] ? 'border-red-400' : 'border-white/8'}`
    return <label htmlFor={id} className={`flex flex-col gap-1.5 text-xs text-[#9ba8b6] ${wide ? 'md:col-span-2' : ''}`}>{label}{hint && <span className="font-normal text-[#5f6f80]">{hint}</span>}{options ? <select id={id} value={String(form[key] ?? '')} onChange={event => set(key, typeof form[key] === 'boolean' ? event.target.value === 'true' : event.target.value)} className={controlClass}>{options.map(option => { const [value, text] = Array.isArray(option) ? option : [option, option]; return <option key={String(value)} value={String(value)}>{text}</option> })}</select> : <input id={id} type={type} min={type === 'number' ? 0 : undefined} placeholder={placeholders[key] || (type === 'date' ? '2026-09-30' : 'Dato requerido')} value={form[key] ?? ''} onChange={event => set(key, type === 'number' ? Number(event.target.value) : event.target.value)} className={controlClass} aria-invalid={Boolean(errors[key])} aria-describedby={errors[key] ? `${id}-error` : undefined} required={['nombre','codigo','fechaInicio','fechaVencimiento'].includes(key)} />}{errors[key] && <span id={`${id}-error`} className="text-red-300">{errors[key]}</span>}</label>
  }
  const rules = isTenant
    ? [
      'Estado automático: Prueba gratuita vigente pasa a Trial y cualquier plan pagado vigente pasa a Activo.',
      'Suspensión manual: el SuperAdmin puede bloquear el negocio aunque su contrato esté vigente y pagado; solo una acción manual puede levantarla.',
      'Suspensión por falta de pago: al vencer el contrato se inicia el período de gracia configurado; con 0 días, la suspensión es inmediata.',
      'Durante la gracia: el negocio conserva temporalmente sus accesos y su estado es Gracia hasta que venza el plazo.',
      'Accesos suspendidos: ningún usuario puede ingresar mientras el negocio permanezca en estado Suspendido.',
      'Reactivación automática: requiere registrar el pago y extender la fecha de vencimiento; el negocio volverá a Activo o Trial si no existe una suspensión manual.',
      'Control manual de cobranza: mantiene el negocio como Vencido hasta que el SuperAdmin revise y actualice su situación.',
      'Integración pendiente: estas reglas están funcionales en el frontend; el backend deberá aplicarlas durante cada inicio de sesión.',
    ]
    : isPlan
      ? ['Un plan define límites y entitlements comerciales; no concede permisos.', 'Los cambios no deben alterar suscripciones existentes sin confirmación.']
      : ['Cada negocio debe conservar al menos 1 y puede tener como máximo 2 Admin Owner activos.', 'Todo administrador activo consume un cupo de usuarios del plan contratado.', 'Un administrador inactivo conserva su registro e historial, no consume cupo y no puede iniciar sesión.', 'No se puede activar un administrador cuando el negocio ya alcanzó el límite de usuarios de su plan.']
  const submit = event => { event.preventDefault(); const next = validateEditor(editor.kind, { ...form, id: editor.value?.id }, records); setErrors(next); if (!Object.keys(next).length) onSave(form) }
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-5 backdrop-blur-sm" onMouseDown={event => { if (event.target === event.currentTarget) onClose() }}>
    <form ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby={titleId} onSubmit={submit} className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl border border-white/10 bg-[#161d28] shadow-[0_24px_60px_rgba(0,0,0,.6)]">
      <header className="flex items-center justify-between border-b border-white/6 px-5 py-4"><div><p id={titleId} className="text-sm font-semibold">{editor.value ? 'Actualizar' : 'Crear'} {isTenant ? 'negocio' : isPlan ? 'plan' : 'administrador'}</p><p className="mt-0.5 text-[11px] text-[#5f6f80]">Solo persistencia de prueba en este navegador</p></div><button type="button" onClick={onClose} aria-label="Cerrar formulario" className="rounded-lg p-2 text-[#9ba8b6] hover:bg-white/6"><X size={16} /></button></header>
      <div className="grid gap-4 p-5 md:grid-cols-2">{isTenant && <>{field('Nombre del negocio *', 'nombre')}{field('Nombre corto', 'nombreCorto', null, 'text', false, 'Se mostrará en espacios reducidos cuando exista.')}{field('RUC / identificación fiscal', 'ruc')}{field('Contacto principal', 'contacto')}{field('Email', 'email', null, 'email')}{field('Teléfono', 'telefono', null, 'tel')}{field('Código URL (slug de acceso) *', 'codigo', null, 'text', true)}<div className="md:col-span-2 -mt-2 rounded-lg border border-[#00c896]/25 bg-[#00c896]/5 px-3 py-2 text-xs text-[#00c896]">🔗 {window.location.origin}/app/{form.codigo || 'codigo-negocio'}</div><div className="md:col-span-2 mt-1 border-t border-white/6 pt-4"><p className="text-[10px] font-semibold uppercase tracking-wide text-[#5f6f80]">Contrato y control de acceso</p></div>{field('Plan contratado', 'plan', planOptions.map(plan => plan.nombre))}{field('Período de pago', 'periodoPago', ['Mensual', 'Trimestral', 'Semestral', 'Anual'])}{field('Fecha de inicio *', 'fechaInicio', null, 'date')}{field('Fecha de vencimiento *', 'fechaVencimiento', null, 'date')}{field('Estado del pago', 'estadoPago', ['Al día', 'Pendiente', 'Vencido'])}<div className="flex flex-col gap-1.5 text-xs text-[#9ba8b6]"><span>Estado del negocio</span><div className="flex min-h-[42px] items-center rounded-lg border border-white/8 bg-[#0e1117] px-3"><Status>{businessState}</Status><span className="ml-2 text-[11px] text-[#5f6f80]">Calculado automáticamente</span></div></div>{field('Política por falta de pago', 'politicaAcceso', ['Suspender al vencer', 'Control manual'], 'text', false, 'La suspensión automática será aplicada por el backend al iniciar sesión.')}{field('Días de gracia', 'diasGracia', null, 'number', false, 'Plazo antes de bloquear el acceso; usa 0 para suspensión inmediata.')}{field('Suspensión administrativa', 'suspensionManual', [[false, 'Sin suspensión manual'], [true, 'Suspender manualmente']], 'text', true, 'Permite bloquear o restablecer el acceso independientemente del estado de pago.')}<div className={`md:col-span-2 rounded-lg border px-3 py-3 text-xs ${accessPreview.allowed ? 'border-emerald-500/25 bg-emerald-500/5 text-emerald-300' : 'border-red-500/25 bg-red-500/5 text-red-300'}`}><strong>{accessPreview.label}</strong><span className="mt-1 block text-[#9ba8b6]">Vista previa de la decisión que deberá validar el sistema durante el inicio de sesión.</span></div></>}{isPlan && <>{field('Nombre del plan', 'nombre')}{field('Precio mensual (PEN)', 'precioMensual', null, 'number')}{field('Máximo de usuarios', 'maxUsuarios', null, 'number')}{field('Máximo de almacenes', 'maxAlmacenes', null, 'number')}</>}{isAdmin && <>{field('Tenant', 'tenant', tenantOptions.map(tenant => tenant.nombre))}{field('Nombre completo', 'nombre')}{field('Correo electrónico', 'email', null, 'email')}{field('Tipo de administrador', 'tipo', ['Admin Owner', 'Admin Tenant'])}<label className={`md:col-span-2 flex cursor-pointer items-start gap-3 rounded-lg border bg-[#0e1117] p-4 ${errors.activo ? 'border-red-400' : 'border-white/8'}`}><input type="checkbox" checked={form.activo === true} onChange={event => set('activo', event.target.checked)} className="mt-0.5 h-4 w-4 accent-[#00c896]" /><span><strong className="block text-sm font-medium text-[#e8edf2]">Administrador activo</strong><span className="mt-1 block text-xs leading-relaxed text-[#5f6f80]">Si está desmarcado, conserva su historial, no consume cupo del plan y no puede iniciar sesión.</span>{errors.activo && <span className="mt-2 block text-xs text-red-300">{errors.activo}</span>}</span></label></>}</div>
      <aside className="border-t border-[#00c896]/20 bg-[#00c896]/5 px-5 py-4"><p className="text-[11px] font-semibold uppercase tracking-[.08em] text-[#00c896]">Cómo funciona este formulario</p><ul className="mt-2 space-y-1 text-xs leading-relaxed text-[#9ba8b6]">{rules.map(rule => <li key={rule}>• {rule}</li>)}</ul></aside>
      <footer className="flex justify-end gap-2 border-t border-white/6 px-5 py-4"><button type="button" onClick={onClose} className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#9ba8b6]">Cancelar</button><button className="rounded-lg bg-[#00c896] px-3 py-2 text-xs font-semibold text-[#082e1e]">Guardar prueba</button></footer>
    </form>
  </div>
}

function Kpi({ label, value, detail, color = '#00c896' }) {
  return <article className="rounded-xl border border-white/8 bg-[#161d28] p-4">
    <div className="mb-3 h-1 w-10 rounded-full" style={{ backgroundColor: color }} />
    <p className="text-[11px] font-semibold uppercase tracking-[.08em] text-[#5f6f80]">{label}</p>
    <p className="mt-1 text-2xl font-semibold text-[#e8edf2]">{value}</p>
    <p className="mt-1 text-xs text-[#9ba8b6]">{detail}</p>
  </article>
}

function Status({ children }) {
  const styles = {
    Activo: 'bg-emerald-500/10 text-emerald-400', Trial: 'bg-blue-500/10 text-blue-400',
    'Por vencer': 'bg-amber-500/10 text-amber-400', Gracia: 'bg-amber-500/10 text-amber-400', Atención: 'bg-amber-500/10 text-amber-400',
    Vencido: 'bg-red-500/10 text-red-400', Suspendido: 'bg-red-500/10 text-red-400',
    Normal: 'bg-emerald-500/10 text-emerald-400',
  }
  return <span className={`inline-flex rounded-full px-2.5 py-1 text-[11px] font-semibold ${styles[children] || 'bg-white/8 text-[#9ba8b6]'}`}>{children}</span>
}

function ConfirmDialog({ action, onCancel, onConfirm }) {
  if (!action) return null
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-5" onMouseDown={event => { if (event.target === event.currentTarget) onCancel() }}>
    <section role="alertdialog" aria-modal="true" aria-labelledby="transition-title" aria-describedby="transition-description" className="w-full max-w-md rounded-2xl border border-amber-500/25 bg-[#161d28] p-5 shadow-2xl">
      <h2 id="transition-title" className="font-semibold">Confirmar cambio a {action.estado}</h2>
      <p id="transition-description" className="mt-2 text-sm text-[#9ba8b6]">El negocio <strong className="text-[#e8edf2]">{action.tenant.nombre}</strong> cambiará de {action.tenant.estado} a {action.estado}. En producción esta operación exigirá motivo, actor e historial de auditoría.</p>
      <div className="mt-5 flex justify-end gap-2"><button autoFocus onClick={onCancel} className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#9ba8b6]">Cancelar</button><button onClick={onConfirm} className="rounded-lg bg-amber-400 px-3 py-2 text-xs font-semibold text-[#2b1a00]">Confirmar cambio</button></div>
    </section>
  </div>
}

function TenantDetail({ tenant, onClose, onEdit = () => {} }) {
  const access = subscriptionAccess(tenant)
  const usage = [
    ['Usuarios', tenantUsage(tenant), tenant.usuariosLimite ? Math.min(100, Math.round((tenant.usuariosActuales / tenant.usuariosLimite) * 100)) : 0, '#3b82f6'],
    ['Productos', '1,284 / 2,000', 64, '#00c896'],
    ['Almacenes', tenant.plan === 'Empresarial' ? '8 / ilimitado' : '3 / 5', 60, '#8b5cf6'],
    ['Storage', '4.8 GB / 10 GB', 48, '#f59e0b'],
  ]
  return <section className="mt-6 overflow-hidden rounded-xl border border-[#00c896]/25 bg-[#161d28] shadow-[0_16px_50px_rgba(0,0,0,.18)]">
    <header className="flex flex-wrap items-start justify-between gap-4 border-b border-white/6 px-5 py-5">
      <div><p className="text-[11px] font-semibold uppercase tracking-[.08em] text-[#00c896]">Detalle 360° · demostración</p><h2 className="mt-1 text-xl font-semibold">{tenant.nombre}</h2><p className="mt-1 text-xs text-[#9ba8b6]">RUC 20123456789 · Código de tenant: demo-{tenant.nombre.split(' ')[0].toLowerCase()}</p></div>
      <button onClick={onClose} className="rounded-lg p-2 text-[#9ba8b6] hover:bg-white/6 hover:text-[#e8edf2]" aria-label="Cerrar detalle"><X size={17} /></button>
    </header>
    <div className="grid gap-5 p-5 xl:grid-cols-3">
      <article className="rounded-lg bg-white/3 p-4"><p className="text-[11px] font-semibold uppercase tracking-wide text-[#5f6f80]">Suscripción</p><div className="mt-3 space-y-2 text-sm"><p><span className="text-[#5f6f80]">Plan</span><strong className="float-right font-medium">{tenant.plan}</strong></p><p><span className="text-[#5f6f80]">Período</span><strong className="float-right font-medium">{tenant.periodoPago || 'Por definir'}</strong></p><p><span className="text-[#5f6f80]">Vigencia</span><strong className="float-right font-medium">{tenant.fechaInicio || '—'} · {tenant.fechaVencimiento || '—'}</strong></p><p><span className="text-[#5f6f80]">Pago</span><span className="float-right"><Status>{tenant.estadoPago || 'Pendiente'}</Status></span></p><p><span className="text-[#5f6f80]">Acceso</span><strong className={`float-right font-medium ${access.allowed ? 'text-emerald-400' : 'text-red-400'}`}>{access.allowed ? 'Habilitado' : 'Desactivado'}</strong></p></div></article>
      <article className="rounded-lg bg-white/3 p-4"><p className="text-[11px] font-semibold uppercase tracking-wide text-[#5f6f80]">Actividad</p><div className="mt-3 space-y-2 text-sm"><p><span className="text-[#5f6f80]">Último acceso</span><strong className="float-right font-medium">{tenant.ultimoAcceso}</strong></p><p><span className="text-[#5f6f80]">Usuarios activos</span><strong className="float-right font-medium">{tenant.admins + 7}</strong></p><p><span className="text-[#5f6f80]">Última operación</span><strong className="float-right font-medium">Hace 24 min</strong></p></div></article>
      <article className="rounded-lg bg-white/3 p-4"><p className="text-[11px] font-semibold uppercase tracking-wide text-[#5f6f80]">Seguridad y soporte</p><div className="mt-3 space-y-2 text-sm"><p><span className="text-[#5f6f80]">Administradores</span><strong className="float-right font-medium">{tenant.admins} activos</strong></p><p><span className="text-[#5f6f80]">MFA</span><strong className="float-right font-medium text-amber-400">Por configurar</strong></p><p><span className="text-[#5f6f80]">Ticket abierto</span><strong className="float-right font-medium">Ninguno</strong></p></div></article>
    </div>
    <div className="border-t border-white/6 px-5 py-5"><p className="mb-4 text-[11px] font-semibold uppercase tracking-[.08em] text-[#5f6f80]">Uso y límites · datos simulados</p><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{usage.map(([label, value, pct, color]) => <div key={label}><div className="mb-1.5 flex justify-between text-xs"><span className="text-[#9ba8b6]">{label}</span><span className="text-[#e8edf2]">{value}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-[#0e1117]"><div className="h-full rounded-full" style={{ width: `${pct}%`, backgroundColor: color }} /></div></div>)}</div></div>
    <div className="border-t border-white/6 px-5 py-5"><div className="mb-4 flex items-center justify-between"><p className="text-[11px] font-semibold uppercase tracking-[.08em] text-[#5f6f80]">Salud del tenant · demostración</p><span className="text-sm font-semibold text-emerald-400">91%</span></div><div className="h-2 overflow-hidden rounded-full bg-[#0e1117]"><div className="h-full w-[91%] rounded-full bg-emerald-400" /></div><div className="mt-4 grid gap-2 text-xs sm:grid-cols-2 xl:grid-cols-3">{[['API', 'Operativa'], ['Base de datos', 'Operativa'], ['Última sincronización', 'Hace 3 min'], ['Login', tenant.ultimoAcceso], ['Notificaciones', 'Operativas'], ['Almacenamiento', '4.8 GB / 10 GB']].map(([label, value]) => <div key={label} className="flex justify-between rounded-lg bg-white/3 px-3 py-2"><span className="text-[#9ba8b6]">{label}</span><span className="text-[#e8edf2]">{value}</span></div>)}</div></div>
    <footer className="flex flex-wrap gap-2 border-t border-white/6 bg-white/2 px-5 py-4"><button onClick={onEdit} className="rounded-lg border border-[#00c896]/30 bg-[#00c896]/10 px-3 py-2 text-xs text-[#00c896]">Editar negocio</button><button onClick={onEdit} className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#9ba8b6]">Cambiar plan</button><button disabled className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#5f6f80] opacity-70">Entrar en modo soporte</button><span className="ml-auto self-center text-[11px] text-[#5f6f80]">Modo soporte inactivo en evaluación</span></footer>
  </section>
}

export function LegacySuperAdminV2App() {
  const [route, setRoute] = useState(readRoute)
  const [menuOpen, setMenuOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [selectedTenant, persistSelectedTenant] = useState(null)
  const [auditFilter, setAuditFilter] = useState('Todos')
  const [alertFilter, setAlertFilter] = useState('Todas')
  const [selectedAdminId, setSelectedAdminId] = useState(null)
  const [tenants, persistTenants] = useDemoStore('stockpro-superadmin-v2-tenants-v4', seedTenants)
  const [plans, setPlans] = useDemoStore('stockpro-superadmin-v2-plans-v3', seedPlans)
  const [tenantAdmins, setTenantAdmins] = useDemoStore('stockpro-superadmin-v2-tenant-admins-v2', seedTenantAdmins)
  const [adminSessions, setAdminSessions] = useDemoStore('stockpro-superadmin-v2-admin-sessions', seedAdminSessions)
  const [platformAudit, setPlatformAudit] = useDemoStore('stockpro-superadmin-v2-audit-events', auditEvents)
  const [editor, setEditor] = useState(null)
  const [pendingTransition, setPendingTransition] = useState(null)
  const section = routeAliases[route] || 'resumen'
  const isAccess = section === 'accesos'
  const metrics = useMemo(() => dashboardMetrics(tenants, plans), [tenants, plans])
  const capabilityPlans = useMemo(() => plans.map(plan => ({ ...seedPlans.find(seed => seed.id === plan.id), ...plan })), [plans])
  const setSelectedTenant = update => {
    const next = typeof update === 'function' ? update(selectedTenant) : update
    if (selectedTenant && next?.estado !== selectedTenant.estado) {
      setPendingTransition(current => ({ ...current, tenant: selectedTenant, estado: next.estado, nextSelected: next }))
      return
    }
    persistSelectedTenant(next)
  }
  const setTenants = update => {
    if (typeof update !== 'function') { persistTenants(update); return }
    const next = update(tenants)
    const changed = next.find(item => tenants.find(previous => previous.id === item.id)?.estado !== item.estado)
    if (changed) {
      const previous = tenants.find(item => item.id === changed.id)
      setPendingTransition(current => ({ ...current, tenant: previous, estado: changed.estado, nextTenants: next }))
      return
    }
    persistTenants(next)
  }
  const setSection = target => {
    const nextRoute = routeAliases[target] ? target : Object.keys(routeAliases).find(key => routeAliases[key] === target) || 'dashboard'
    setRoute(nextRoute)
    writeRoute(nextRoute)
    setMenuOpen(false)
  }
  useEffect(() => {
    const syncRoute = () => setRoute(readRoute())
    window.addEventListener('hashchange', syncRoute)
    return () => window.removeEventListener('hashchange', syncRoute)
  }, [])
  const visibleTenants = useMemo(() => tenants.filter(t => t.nombre.toLowerCase().includes(query.toLowerCase())), [query, tenants])
  const visibleAudit = useMemo(() => auditFilter === 'Todos' ? platformAudit : platformAudit.filter(event => event.tipo === auditFilter), [auditFilter, platformAudit])
  const visibleAlerts = useMemo(() => alertFilter === 'Todas' ? platformAlerts : platformAlerts.filter(alert => alert.categoria === alertFilter), [alertFilter])
  const saveEditor = (data) => {
    if (editor.kind === 'tenant') {
      const normalized = { ...editor.value, ...data, estado: deriveBusinessState({ ...editor.value, ...data }) }
      const record = { ...normalized, usuarios: tenantUsage(normalized), id: editor.value?.id || `tenant-${Date.now()}` }
      setTenants(current => editor.value ? current.map(item => item.id === record.id ? record : item) : [record, ...current])
    }
    if (editor.kind === 'plan') {
      const normalized = { ...editor.value, ...data, clientes: editor.value?.clientes ?? 0, color: editor.value?.color ?? '#00c896' }
      const record = { ...normalized, id: editor.value?.id || `plan-${Date.now()}`, mrr: formatMoney(normalized.precioMensual * normalized.clientes), limite: formatPlanLimit(normalized) }
      setPlans(current => editor.value ? current.map(item => item.id === record.id ? record : item) : [...current, record])
    }
    if (editor.kind === 'admin') {
      const record = { ...editor.value, ...data, id: editor.value?.id || `admin-${Date.now()}` }
      setTenantAdmins(current => editor.value ? current.map(item => item.id === record.id ? record : item) : [record, ...current])
      setPlatformAudit(current => [{ fecha:'Ahora', actor:'SuperAdmin', accion:editor.value ? 'Actualizó administrador' : 'Creó administrador', recurso:`${record.nombre} · ${record.tenant}`, tipo:'Seguridad', resultado:'Exitoso' }, ...current])
    }
    setEditor(null)
  }
  const revokeSession = session => {
    const admin = tenantAdmins.find(item => item.id === session.adminId)
    setAdminSessions(current => current.map(item => item.id === session.id ? { ...item, activa:false, ultimoAcceso:'Revocada ahora' } : item))
    setPlatformAudit(current => [{ fecha:'Ahora', actor:'SuperAdmin', accion:'Revocó sesión', recurso:`${admin?.nombre || 'Administrador'} · ${session.dispositivo}`, tipo:'Seguridad', resultado:'Exitoso' }, ...current])
  }

  return <main data-landing className="min-h-screen bg-[#0e1117] text-[#e8edf2]">
    <style>{'@media (min-width:1280px){section>.grid:has(+article.border-amber-500\\/25.bg-amber-500\\/5){grid-template-columns:repeat(2,minmax(0,1fr))}}'}</style>
    <header className="sticky top-0 z-10 flex min-h-16 items-center justify-between border-b border-white/8 bg-[#141920]/95 px-5 backdrop-blur md:px-8">
      <div className="flex items-center gap-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#00c896]/15 text-[#00c896]"><ShieldCheck size={20} /></div>
        <div><p className="font-semibold">StockPro · SuperAdmin V2</p><p className="text-[11px] text-[#5f6f80]">Vista aislada de evaluación</p></div>
      </div>
      <div className="flex items-center gap-2"><span className="hidden rounded-full border border-amber-500/25 bg-amber-500/10 px-3 py-1.5 text-[11px] font-semibold text-amber-300 sm:block">SIN CONEXIÓN A DATOS REALES</span><button type="button" onClick={() => setMenuOpen(value => !value)} aria-expanded={menuOpen} aria-controls="superadmin-navigation" aria-label="Abrir menú" className="rounded-lg border border-white/8 p-2 text-[#9ba8b6] lg:hidden"><Menu size={18} /></button></div>
    </header>

    <div className="mx-auto grid max-w-[1500px] grid-cols-1 lg:grid-cols-[220px_minmax(0,1fr)]">
      <nav id="superadmin-navigation" aria-label="Navegación de SuperAdmin" className={`${menuOpen ? 'block' : 'hidden'} border-b border-white/8 bg-[#0f1520] p-3 lg:block lg:min-h-[calc(100vh-64px)] lg:border-b-0 lg:border-r`}>
        <p className="mb-4 px-3 text-[11px] font-bold tracking-[.12em] text-[#e8edf2]">STOCKPRO</p>
        {navGroups.map(group => <div key={group.label || 'dashboard'} className="mb-4">{group.label && <p className="mb-1 px-3 text-[10px] font-semibold tracking-[.1em] text-[#5f6f80]">{group.label}</p>}{group.items.map(([id, label, icon]) => <button key={id} onClick={() => setSection(id)} aria-current={route === id ? 'page' : undefined} className={`mb-0.5 flex w-full items-center gap-2.5 rounded-lg px-3 py-2 text-left text-[13px] transition-colors ${route === id ? 'bg-[#00c896]/12 text-[#00c896]' : 'text-[#9ba8b6] hover:bg-white/5 hover:text-[#e8edf2]'}`}>{createElement(icon, { size: 14 })}{label}</button>)}</div>)}
      </nav>

      <section className="min-w-0 p-5 md:p-8">
        {section === 'resumen' && <>
          <div className="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p className="text-[12px] text-[#00c896]">CENTRO DE CONTROL</p><h1 className="text-2xl font-semibold">Estado de la plataforma</h1><p className="mt-1 text-sm text-[#9ba8b6]">Indicadores de ejemplo para validar la estructura y prioridad de información.</p></div><p className="text-xs text-[#5f6f80]">Datos simulados · no se consulta la API</p></div>
          <div className="grid grid-cols-2 gap-3 xl:grid-cols-4"><Kpi label="Tenants activos" value={metrics.activos} detail={`de ${metrics.totalTenants} registrados`} /><Kpi label="MRR estimado" value={formatMoney(metrics.mrr)} detail="según planes de prueba" color="#f59e0b" /><Kpi label="Usuarios registrados" value={tenants.reduce((sum, item) => sum + (item.usuariosActuales || 0), 0)} detail="en tenants de prueba" color="#3b82f6" /><Kpi label="Requieren atención" value={metrics.atencion} detail="uso o suscripción" color="#ef4444" /></div>
          <div className="mt-6 grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><div className="mb-4 flex items-center justify-between"><h2 className="font-semibold">Requiere atención</h2><button onClick={() => setSection('tenants')} className="text-xs text-[#00c896]">Ver clientes</button></div>{['1 tenant venció hoy', '2 tenants alcanzaron 80% de usuarios', '1 administrador lleva más de 90 días inactivo'].map((text, i) => <div key={text} className="flex items-center gap-3 border-t border-white/6 py-3 first:border-t-0"><AlertTriangle size={16} className={i === 0 ? 'text-red-400' : 'text-amber-400'} /><span className="flex-1 text-sm text-[#9ba8b6]">{text}</span><ChevronRight size={15} className="text-[#5f6f80]" /></div>)}</article><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><h2 className="mb-4 font-semibold">Límites de esta fase</h2><div className="space-y-3 text-sm text-[#9ba8b6]"><p className="flex gap-2"><CheckCircle2 size={16} className="shrink-0 text-[#00c896]" />Prototipo visual y navegación</p><p className="flex gap-2"><CheckCircle2 size={16} className="shrink-0 text-[#00c896]" />Sin escrituras ni lecturas de tablas</p><p className="flex gap-2"><Clock3 size={16} className="shrink-0 text-amber-400" />ACE y Approval Engine pendientes</p></div></article></div>
        </>}

        {section === 'tenants' && <><div className="mb-5"><p className="text-[12px] text-[#00c896]">CLIENTES</p><h1 className="text-2xl font-semibold">Tenants y estado comercial</h1></div><label className="mb-4 flex max-w-md items-center gap-2 rounded-lg border border-white/8 bg-[#161d28] px-3 py-2"><Search size={15} className="text-[#5f6f80]" /><input value={query} onChange={e => setQuery(e.target.value)} className="w-full bg-transparent text-sm outline-none placeholder:text-[#5f6f80]" placeholder="Buscar tenant de demostración" /></label><div className="overflow-x-auto rounded-xl border border-white/8"><table className="w-full min-w-[810px] text-left text-sm"><thead className="bg-white/3 text-[11px] uppercase tracking-wide text-[#5f6f80]"><tr>{['Tenant', 'Plan', 'Estado', 'Administradores', 'Usuarios', 'Actividad', 'Riesgo', ''].map(h => <th key={h || 'acciones'} className="px-4 py-3 font-semibold">{h}</th>)}</tr></thead><tbody>{visibleTenants.map(t => <tr key={t.nombre} className="border-t border-white/6 text-[#9ba8b6]"><td className="px-4 py-4 font-medium text-[#e8edf2]">{t.nombre}</td><td className="px-4 py-4">{t.plan}</td><td className="px-4 py-4"><Status>{t.estado}</Status></td><td className="px-4 py-4">{t.admins}</td><td className="px-4 py-4">{t.usuarios}</td><td className="px-4 py-4">{t.ultimoAcceso}</td><td className="px-4 py-4"><Status>{t.riesgo}</Status></td><td className="px-4 py-4"><button onClick={() => setSelectedTenant(t)} className="whitespace-nowrap text-xs font-medium text-[#00c896] hover:underline">Ver 360°</button></td></tr>)}</tbody></table></div>{selectedTenant && <TenantDetail tenant={selectedTenant} onClose={() => setSelectedTenant(null)} />}</>}

        {isAccess && <><div className="mb-6"><p className="text-[12px] text-[#00c896]">GESTIÓN TRANSITORIA</p><h1 className="text-2xl font-semibold">Usuarios, roles y accesos</h1><p className="mt-1 max-w-3xl text-sm text-[#9ba8b6]">Esta superficie supervisa el modelo vigente. No crea permisos, políticas ni decisiones; ACE será la fuente de autorización cuando se complete la integración.</p></div><div className="mb-5 rounded-xl border border-blue-500/25 bg-blue-500/8 p-4 text-sm text-blue-200"><div className="flex gap-2"><KeyRound size={17} className="mt-0.5 shrink-0" /><p><strong>Modo de evaluación:</strong> las acciones de alta, baja, cambio de rol, sesiones y restablecimiento están deliberadamente inactivas. Su activación futura requerirá APIs auditadas y aprobación de alcance.</p></div></div><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><h2 className="mb-4 font-semibold">Controles recomendados</h2><div className="space-y-3">{[['Owner protegido', 'No permitir dejar un tenant sin propietario.'], ['Administradores válidos', 'Alertar si no hay un administrador activo adicional.'], ['Sesiones', 'Preparar consulta y revocación por dispositivo.'], ['Auditoría', 'Registrar cambios de usuario y rol, sin borrar eventos.']].map(([title, desc]) => <div key={title} className="rounded-lg bg-white/3 p-3"><p className="font-medium text-[#e8edf2]">{title}</p><p className="mt-1 text-xs text-[#9ba8b6]">{desc}</p></div>)}</div></article><article className="rounded-xl border border-white/8 bg-[#161d28]"><div className="border-b border-white/6 px-5 py-4"><h2 className="font-semibold">Mapa de roles actual · ejemplo</h2></div>{roles.map(r => <div key={r.nombre} className="flex items-center gap-3 border-b border-white/6 px-5 py-4 last:border-0"><span className="h-9 w-1 rounded-full" style={{ backgroundColor: r.color }} /><div className="min-w-0 flex-1"><p className="font-medium text-[#e8edf2]">{r.nombre}</p><p className="text-xs text-[#5f6f80]">{r.tipo} · {r.usuarios} usuarios</p></div><span className="text-xs text-[#9ba8b6]">{r.acceso}</span></div>)}</article></div></>}

        {section === 'suscripciones' && <><div className="mb-6"><p className="text-[12px] text-[#00c896]">SUSCRIPCIONES</p><h1 className="text-2xl font-semibold">Planes, renovaciones y uso</h1><p className="mt-1 text-sm text-[#9ba8b6]">Modelo visual para revisar información comercial y límites sin modificar planes reales.</p></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">{plans.map(plan => <article key={plan.nombre} className="rounded-xl border border-white/8 bg-[#161d28] p-5"><div className="flex items-center justify-between"><h2 className="font-semibold">{plan.nombre}</h2><span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: plan.color }} /></div><p className="mt-5 text-2xl font-semibold">{plan.mrr}</p><p className="text-xs text-[#5f6f80]">MRR estimado · {plan.clientes} clientes</p><p className="mt-4 border-t border-white/6 pt-3 text-xs text-[#9ba8b6]">{plan.limite}</p></article>)}</div><div className="mt-6 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><h2 className="mb-4 font-semibold">Próximas renovaciones</h2>{[['Hoy', 'Logística Andina EIRL', 'Básico', 'S/ 49'], ['31 ago', 'Almacenes Sur Perú', 'Prueba gratuita', 'Conversión pendiente'], ['02 sep', 'Comercial Pacífico SAC', 'Empresarial', 'S/ 199']].map(row => <div key={row[1]} className="grid grid-cols-[70px_1fr_auto] gap-3 border-t border-white/6 py-3 text-sm"><span className="text-[#5f6f80]">{row[0]}</span><span><strong className="font-medium text-[#e8edf2]">{row[1]}</strong><span className="block text-xs text-[#5f6f80]">{row[2]}</span></span><span className="text-[#9ba8b6]">{row[3]}</span></div>)}</article><article className="rounded-xl border border-amber-500/20 bg-amber-500/5 p-5"><BellRing size={19} className="text-amber-400" /><h2 className="mt-3 font-semibold">Decisión pendiente</h2><p className="mt-2 text-sm text-[#9ba8b6]">La conexión de pagos y facturación se mantiene fuera del alcance de esta demostración. Aquí se validan solamente los indicadores y flujos.</p></article></div></>}

        {section === 'alertas' && <><div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p className="text-[12px] text-[#00c896]">CENTRO DE ALERTAS</p><h1 className="text-2xl font-semibold">Eventos que requieren atención</h1><p className="mt-1 text-sm text-[#9ba8b6]">Visión consolidada de suscripción, límites, seguridad y operación.</p></div><span className="rounded-full border border-amber-500/25 bg-amber-500/10 px-3 py-1.5 text-xs font-semibold text-amber-300">3 abiertas</span></div><div className="mb-4 flex flex-wrap gap-2">{['Todas', 'Suscripción', 'Límites', 'Seguridad', 'Operación'].map(filter => <button key={filter} onClick={() => setAlertFilter(filter)} className={`rounded-lg px-3 py-2 text-xs font-medium transition-colors ${alertFilter === filter ? 'bg-[#00c896] text-[#082e1e]' : 'border border-white/8 bg-[#161d28] text-[#9ba8b6] hover:bg-white/5'}`}>{filter}</button>)}</div><div className="space-y-3">{visibleAlerts.map(alert => <article key={alert.titulo} className="flex flex-wrap items-center gap-4 rounded-xl border border-white/8 bg-[#161d28] p-4"><span className={`h-2.5 w-2.5 rounded-full ${alert.severidad === 'Alta' ? 'bg-red-400' : alert.severidad === 'Media' ? 'bg-amber-400' : 'bg-blue-400'}`} /><div className="min-w-[220px] flex-1"><p className="font-medium text-[#e8edf2]">{alert.titulo}</p><p className="mt-1 text-xs text-[#9ba8b6]">{alert.detalle}</p></div><div className="flex items-center gap-2"><Status>{alert.categoria}</Status><Status>{alert.estado}</Status></div><button disabled className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#5f6f80]">Ver detalle</button></article>)}</div><div className="mt-5 rounded-xl border border-blue-500/20 bg-blue-500/6 p-4 text-sm text-blue-100">En producción, cada alerta deberá definir fuente, severidad, responsable, política de escalación y ciclo de resolución auditado. Esta vista no crea ni cierra alertas reales.</div></>}

        {section === 'operacion' && <><div className="mb-6"><p className="text-[12px] text-[#00c896]">OPERACIÓN SAAS</p><h1 className="text-2xl font-semibold">Salud, alertas y continuidad</h1></div><div className="grid gap-3 md:grid-cols-3"><Kpi label="Salud de plataforma" value="96%" detail="Servicios críticos operativos" color="#22c55e" /><Kpi label="Backups verificados" value="1 / 1" detail="Última prueba: hoy, 03:00" color="#3b82f6" /><Kpi label="Alertas abiertas" value="3" detail="2 comerciales · 1 acceso" color="#f59e0b" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><div className="mb-4 flex items-center gap-2"><HeartPulse size={18} className="text-[#00c896]" /><h2 className="font-semibold">Actividad reciente</h2></div>{events.map(([fecha, titulo, detalle, tipo]) => <div key={`${fecha}-${titulo}`} className="flex gap-3 border-t border-white/6 py-3"><span className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${tipo === 'warning' ? 'bg-amber-400' : tipo === 'info' ? 'bg-blue-400' : 'bg-emerald-400'}`} /><div className="min-w-0 flex-1"><p className="text-sm text-[#e8edf2]">{titulo}</p><p className="text-xs text-[#5f6f80]">{detalle}</p></div><span className="text-xs text-[#5f6f80]">{fecha}</span></div>)}</article><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><HardDrive size={19} className="text-blue-400" /><h2 className="mt-3 font-semibold">Backups y soporte</h2><p className="mt-2 text-sm text-[#9ba8b6]">Se muestran como información de evaluación. Las restauraciones, exportaciones y modo soporte no están conectados ni pueden ejecutarse.</p><div className="mt-4 flex items-center gap-2 text-xs text-[#5f6f80]"><Headphones size={14} />Requiere diseño de procedimientos auditados.</div></article></div></>}

        {section === 'seguridad' && <><div className="mb-6"><p className="text-[12px] text-[#00c896]">SEGURIDAD DE PLATAFORMA</p><h1 className="text-2xl font-semibold">Administradores, sesiones y eventos</h1><p className="mt-1 text-sm text-[#9ba8b6]">Supervisión visual. Las acciones sensibles permanecen deshabilitadas hasta definir sus APIs, auditoría y MFA.</p></div><div className="grid gap-5 xl:grid-cols-2"><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><div className="flex items-center gap-2"><UserCog size={18} className="text-[#00c896]" /><h2 className="font-semibold">Administradores de plataforma</h2></div>{[['Andrea Ramos', 'Activo · MFA pendiente', 'Último acceso hace 1 h'], ['Carlos Medina', 'Activo · MFA pendiente', 'Último acceso ayer']].map(([nombre, estado, acceso]) => <div key={nombre} className="mt-4 flex items-center gap-3 rounded-lg bg-white/3 p-3"><CircleUserRound size={28} className="text-[#5f6f80]" /><div className="flex-1"><p className="font-medium text-[#e8edf2]">{nombre}</p><p className="text-xs text-amber-400">{estado}</p></div><p className="text-right text-xs text-[#5f6f80]">{acceso}</p></div>)}</article><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><div className="flex items-center gap-2"><MonitorSmartphone size={18} className="text-blue-400" /><h2 className="font-semibold">Sesiones de ejemplo</h2></div>{[['Windows · Chrome', 'Activo ahora'], ['macOS · Safari', 'Hace 1 día']].map(([device, estado]) => <div key={device} className="mt-4 flex items-center justify-between rounded-lg bg-white/3 p-3"><div><p className="text-sm font-medium text-[#e8edf2]">{device}</p><p className="text-xs text-[#5f6f80]">Ubicación y dirección IP se definirán con la política de privacidad.</p></div><Status>{estado}</Status></div>)}<div className="mt-4 rounded-lg border border-blue-500/20 bg-blue-500/8 p-3 text-xs text-blue-200">La revocación de sesiones, MFA y alertas de actividad sospechosa son mejoras futuras de seguridad, no capacidades de ACE.</div></article></div></>}

        {section === 'auditoria' && <><div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p className="text-[12px] text-[#00c896]">AUDITORÍA DE PLATAFORMA</p><h1 className="text-2xl font-semibold">Bitácora de acciones administrativas</h1><p className="mt-1 text-sm text-[#9ba8b6]">Traza separada de la auditoría operativa del tenant. En producción, estos eventos serán inmutables y con retención definida.</p></div><span className="rounded-full border border-blue-500/20 bg-blue-500/8 px-3 py-1.5 text-xs text-blue-300">Datos de demostración</span></div><div className="mb-4 flex flex-wrap gap-2">{['Todos', 'Seguridad', 'Suscripción', 'Operación', 'Soporte', 'Alerta'].map(filter => <button key={filter} onClick={() => setAuditFilter(filter)} className={`rounded-lg px-3 py-2 text-xs font-medium transition-colors ${auditFilter === filter ? 'bg-[#00c896] text-[#082e1e]' : 'border border-white/8 bg-[#161d28] text-[#9ba8b6] hover:bg-white/5'}`}>{filter}</button>)}</div><div className="overflow-x-auto rounded-xl border border-white/8 bg-[#161d28]"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-white/3 text-[11px] uppercase tracking-wide text-[#5f6f80]"><tr>{['Fecha', 'Actor', 'Acción', 'Recurso', 'Tipo', 'Resultado'].map(head => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody>{visibleAudit.map(event => <tr key={`${event.fecha}-${event.accion}`} className="border-t border-white/6"><td className="px-4 py-4 text-xs text-[#5f6f80]">{event.fecha}</td><td className="px-4 py-4 font-medium text-[#e8edf2]">{event.actor}</td><td className="px-4 py-4 text-[#9ba8b6]">{event.accion}</td><td className="px-4 py-4 text-[#9ba8b6]">{event.recurso}</td><td className="px-4 py-4"><Status>{event.tipo}</Status></td><td className="px-4 py-4"><Status>{event.resultado}</Status></td></tr>)}</tbody></table></div><div className="mt-5 grid gap-3 md:grid-cols-3"><article className="rounded-xl border border-white/8 bg-[#161d28] p-4"><p className="text-xs font-semibold text-[#e8edf2]">Qué se debe registrar</p><p className="mt-1 text-xs text-[#9ba8b6]">Actor, tenant, acción, recurso, resultado, motivo y correlación.</p></article><article className="rounded-xl border border-white/8 bg-[#161d28] p-4"><p className="text-xs font-semibold text-[#e8edf2]">Qué no se debe permitir</p><p className="mt-1 text-xs text-[#9ba8b6]">Borrar, editar o limpiar eventos por usuarios normales.</p></article><article className="rounded-xl border border-white/8 bg-[#161d28] p-4"><p className="text-xs font-semibold text-[#e8edf2]">Futura correlación</p><p className="mt-1 text-xs text-[#9ba8b6]">Preparar request_id y correlation_id para ACE y Approval Engine.</p></article></div></>}

        {section === 'marketing' && <><div className="mb-6"><p className="text-[12px] text-[#00c896]">MARKETING</p><h1 className="text-2xl font-semibold">Landing y adquisición</h1><p className="mt-1 text-sm text-[#9ba8b6]">Propuesta de gestión visual separada de la landing pública que ya opera en StockPro.</p></div><div className="grid gap-3 md:grid-cols-3"><Kpi label="Visitas del mes" value="2,840" detail="+12% vs. período anterior" color="#3b82f6" /><Kpi label="Solicitudes de demo" value="86" detail="3.0% de conversión" color="#00c896" /><Kpi label="Trials iniciados" value="24" detail="28% desde solicitud" color="#8b5cf6" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><article className="overflow-hidden rounded-xl border border-white/8 bg-[#161d28]"><div className="flex items-center justify-between border-b border-white/6 px-5 py-4"><div><p className="font-semibold">Contenido de Landing</p><p className="text-xs text-[#5f6f80]">Versión simulada · sin publicar</p></div><button disabled className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#5f6f80]">Vista previa</button></div><div className="space-y-3 p-5">{[['Hero principal', 'Control de inventario y logística para crecer sin fricción.'], ['Prueba social', 'Empresas que ordenan su operación con StockPro.'], ['Planes públicos', 'Prueba gratuita · Básico · Profesional · Empresarial'], ['SEO y metadatos', 'Título, descripción y Open Graph por validar.']].map(([title, text]) => <div key={title} className="rounded-lg bg-white/3 p-3"><p className="text-sm font-medium text-[#e8edf2]">{title}</p><p className="mt-1 text-xs text-[#9ba8b6]">{text}</p></div>)}</div></article><div className="space-y-5"><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><div className="flex items-center gap-2"><BarChart3 size={18} className="text-blue-400" /><h2 className="font-semibold">Embudo de conversión</h2></div>{[['Visitas', '2,840', 100], ['Solicitud de demo', '86', 38], ['Trial', '24', 21], ['Cliente', '9', 12]].map(([label, value, width]) => <div key={label} className="mt-4"><div className="mb-1 flex justify-between text-xs"><span className="text-[#9ba8b6]">{label}</span><span className="text-[#e8edf2]">{value}</span></div><div className="h-2 overflow-hidden rounded-full bg-[#0e1117]"><div className="h-full rounded-full bg-blue-400" style={{ width: `${width}%` }} /></div></div>)}</article><article className="rounded-xl border border-amber-500/20 bg-amber-500/5 p-5"><MousePointerClick size={19} className="text-amber-400" /><h2 className="mt-3 font-semibold">Siguiente decisión</h2><p className="mt-2 text-sm text-[#9ba8b6]">Definir qué métricas reales se medirán, su proveedor de analítica y el consentimiento/cookies antes de conectar este módulo.</p></article></div></div></>}

        {section === 'soporte' && <><div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p className="text-[12px] text-[#00c896]">SOPORTE</p><h1 className="text-2xl font-semibold">Casos, recuperación y modo soporte</h1><p className="mt-1 text-sm text-[#9ba8b6]">La interfaz valida el procedimiento sin permitir acceso silencioso a la operación de un cliente.</p></div><button disabled className="rounded-lg border border-white/8 bg-[#161d28] px-3 py-2 text-xs text-[#5f6f80]">Nuevo caso</button></div><div className="mb-5 flex gap-3 rounded-xl border border-amber-500/30 bg-amber-500/8 p-4" role="status"><AlertTriangle size={20} className="mt-0.5 shrink-0 text-amber-400" /><div><p className="text-sm font-semibold text-amber-200">Módulo demostrativo · backend pendiente de desarrollo</p><p className="mt-1 text-xs leading-relaxed text-amber-100/75">Los casos, indicadores y tiempos mostrados son datos de maqueta. Todavía no existe persistencia en PostgreSQL, APIs de soporte, auditoría autoritativa ni acceso real a las cuentas de clientes.</p></div></div><div className="grid gap-3 md:grid-cols-3"><Kpi label="Casos abiertos" value="2" detail="1 requiere revisión hoy" color="#f59e0b" /><Kpi label="Tiempo medio" value="3 h 20 m" detail="Resolución de casos demo" color="#3b82f6" /><Kpi label="Accesos soporte" value="0" detail="Ninguno activo ahora" color="#00c896" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><article className="overflow-hidden rounded-xl border border-white/8 bg-[#161d28]"><div className="flex items-center gap-2 border-b border-white/6 px-5 py-4"><MessageSquareText size={18} className="text-[#00c896]" /><h2 className="font-semibold">Casos de demostración</h2></div>{supportCases.map(item => <div key={item.codigo} className="grid grid-cols-[auto_1fr_auto] gap-3 border-b border-white/6 px-5 py-4 last:border-0"><div className="mt-1 h-2 w-2 rounded-full bg-amber-400" /><div><p className="text-sm font-medium text-[#e8edf2]">{item.asunto}</p><p className="mt-1 text-xs text-[#5f6f80]">{item.codigo} · {item.tenant} · {item.actualizado}</p></div><div className="text-right"><Status>{item.estado}</Status><p className="mt-1 text-[11px] text-[#9ba8b6]">{item.prioridad}</p></div></div>)}</article><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><h2 className="font-semibold">Flujo obligatorio</h2><div className="mt-4 space-y-3">{[['1', 'Registrar caso', 'Motivo, tenant, solicitante y evidencia.'], ['2', 'Verificar identidad', 'Nunca recuperar acceso solo por llamada o mensaje.'], ['3', 'Aprobar intervención', 'Motivo y alcance antes de modo soporte.'], ['4', 'Auditar y cerrar', 'Inicio, fin y acciones realizadas.']].map(([num, title, desc]) => <div key={num} className="flex gap-3"><span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-[#00c896]/15 text-xs font-semibold text-[#00c896]">{num}</span><div><p className="text-sm font-medium text-[#e8edf2]">{title}</p><p className="text-xs text-[#9ba8b6]">{desc}</p></div></div>)}</div><div className="mt-5 rounded-lg border border-amber-500/20 bg-amber-500/5 p-3 text-xs text-amber-200">Modo soporte y recuperación crítica: visibles como proceso, deshabilitados hasta contar con APIs auditadas y aprobación operativa.</div></article></div></>}

        {section === 'integracion' && <><div className="mb-6"><p className="text-[12px] text-[#00c896]">PREPARACIÓN FUTURA</p><h1 className="text-2xl font-semibold">Gates de integración y reversibilidad</h1><p className="mt-1 max-w-3xl text-sm text-[#9ba8b6]">Esta pantalla no activa ACE ni Approval Engine. Permite evaluar cuándo existe evidencia suficiente para iniciar el plan de integración autorizado.</p></div><div className="grid gap-5 xl:grid-cols-2"><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><h2 className="font-semibold">Access Control Engine · ACE</h2><p className="mt-1 text-xs text-[#5f6f80]">Estado declarado: en construcción</p><div className="mt-4 space-y-3">{[['Standalone V1 — Integration Ready', false], ['Integration Lab con aplicación independiente', false], ['Contratos API/SDK versionados y congelados', false], ['Aislamiento cross-tenant y cross-application validado', false], ['Observabilidad y runbooks disponibles', false]].map(([item, ready]) => <div key={item} className="flex items-center gap-2 text-sm"><span className={`h-2.5 w-2.5 rounded-full ${ready ? 'bg-emerald-400' : 'bg-[#5f6f80]'}`} /><span className={ready ? 'text-[#e8edf2]' : 'text-[#9ba8b6]'}>{item}</span></div>)}</div></article><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><h2 className="font-semibold">Approval Engine</h2><p className="mt-1 text-xs text-[#5f6f80]">Estado declarado: en construcción</p><div className="mt-4 space-y-3">{[['Standalone V1 — Integration Ready', false], ['Integration Lab con aplicación independiente', false], ['Idempotencia, reintentos y fail-closed validados', false], ['Eventos y autenticación de servicio validados', false], ['Aprobación formal GO para iniciar integración', false]].map(([item, ready]) => <div key={item} className="flex items-center gap-2 text-sm"><span className={`h-2.5 w-2.5 rounded-full ${ready ? 'bg-emerald-400' : 'bg-[#5f6f80]'}`} /><span className={ready ? 'text-[#e8edf2]' : 'text-[#9ba8b6]'}>{item}</span></div>)}</div></article></div><article className="mt-5 rounded-xl border border-blue-500/20 bg-blue-500/6 p-5"><h2 className="font-semibold text-blue-100">Ruta autorizada cuando los gates estén completos</h2><div className="mt-4 grid gap-3 md:grid-cols-4">{[['1', 'Inventario', 'Mapear roles, permisos y procesos actuales.'], ['2', 'Adapters', 'AccessControlPort y ApprovalPort sin llamadas dispersas.'], ['3', 'Shadow mode', 'Comparar decisiones sin bloquear la operación.'], ['4', 'Pilot y rollout', 'Cohortes pequeñas, flags auditables y rollback.']].map(([num, title, text]) => <div key={num} className="rounded-lg bg-[#0e1117]/45 p-3"><span className="text-xs font-semibold text-blue-300">{num}</span><p className="mt-1 text-sm font-medium text-[#e8edf2]">{title}</p><p className="mt-1 text-xs text-[#9ba8b6]">{text}</p></div>)}</div><div className="mt-5 rounded-lg border border-amber-500/20 bg-amber-500/5 p-3 text-xs text-amber-200">Mientras cualquiera de estos gates esté pendiente, StockPro conserva sus controles actuales y no integra ni duplica los motores.</div></article></>}
        {section === 'accesos' && <><div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p className="text-[12px] text-[#00c896]">USUARIOS Y ROLES</p><h1 className="text-2xl font-semibold">Administradores de tenant y roles</h1><p className="mt-1 max-w-3xl text-sm text-[#9ba8b6]">El SuperAdmin registra los administradores base de cada tenant. El Owner es responsable máximo y protegido; el Admin Tenant gestiona la operación administrativa cotidiana.</p></div><button onClick={() => setEditor({ kind: 'admin' })} className="rounded-lg bg-[#00c896] px-3 py-2 text-xs font-semibold text-[#082e1e]">Nuevo administrador</button></div><div className="mb-5 grid gap-3 md:grid-cols-2"><article className="rounded-xl border border-amber-500/25 bg-amber-500/5 p-4"><p className="font-semibold text-amber-200">Admin Owner</p><p className="mt-1 text-sm text-[#9ba8b6]">Rol fijo y protegido. Debe existir al menos uno por tenant; no puede quitarse el último Owner ni dejar la empresa sin responsable.</p></article><article className="rounded-xl border border-blue-500/25 bg-blue-500/5 p-4"><p className="font-semibold text-blue-200">Admin Tenant</p><p className="mt-1 text-sm text-[#9ba8b6]">Administrador delegado. Gestiona usuarios y roles dinámicos de su empresa dentro de los límites y permisos vigentes.</p></article></div><div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><article className="overflow-hidden rounded-xl border border-white/8 bg-[#161d28]"><div className="border-b border-white/6 px-5 py-4"><h2 className="font-semibold">Administradores registrados · prueba local</h2></div>{tenantAdmins.map(admin => <div key={admin.id} className="flex flex-wrap items-center gap-3 border-b border-white/6 px-5 py-4 last:border-0"><CircleUserRound size={28} className="text-[#5f6f80]" /><div className="min-w-[180px] flex-1"><p className="font-medium text-[#e8edf2]">{admin.nombre}</p><p className="text-xs text-[#5f6f80]">{admin.email} · {admin.tenant}</p></div><Status>{admin.tipo}</Status><span className={`rounded-full px-2.5 py-1 text-[11px] font-semibold ${canAdminAuthenticate(admin) ? 'bg-emerald-500/10 text-emerald-400' : 'bg-red-500/10 text-red-400'}`}>{canAdminAuthenticate(admin) ? 'Activo' : 'Inactivo'}</span><button onClick={() => setEditor({ kind: 'admin', value: admin })} className="text-xs font-medium text-[#00c896] hover:underline">Editar</button></div>)}</article><article className="rounded-xl border border-white/8 bg-[#161d28] p-5"><h2 className="font-semibold">Gobierno de roles</h2><div className="mt-4 space-y-3 text-sm"><div className="rounded-lg bg-white/3 p-3"><p className="font-medium text-[#e8edf2]">Roles fijos · SuperAdmin</p><p className="mt-1 text-xs text-[#9ba8b6]">Define y protege el catálogo base: Admin Owner, Admin Tenant y roles estándar habilitados.</p></div><div className="rounded-lg bg-white/3 p-3"><p className="font-medium text-[#e8edf2]">Roles dinámicos · Admin Tenant</p><p className="mt-1 text-xs text-[#9ba8b6]">Crea y mantiene roles personalizados usando únicamente el catálogo permitido; no crea permisos nuevos.</p></div><div className="rounded-lg border border-amber-500/20 bg-amber-500/5 p-3 text-xs text-amber-200">Esta maqueta no sustituye ACE. Conserva la administración actual hasta que el motor externo esté listo.</div></div></article></div></>}

        {section === 'tenants' && <div className="mt-5 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/8 bg-[#161d28] p-4"><p className="text-sm text-[#9ba8b6]">Las altas y cambios se guardan únicamente en el almacenamiento local de este navegador.</p><div className="flex gap-2"><button onClick={() => setEditor({ kind: 'tenant' })} className="rounded-lg bg-[#00c896] px-3 py-2 text-xs font-semibold text-[#082e1e]">Nuevo negocio</button><button disabled={!selectedTenant} onClick={() => setEditor({ kind: 'tenant', value: selectedTenant })} className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#9ba8b6] disabled:opacity-40">Editar seleccionado</button><button onClick={() => { setTenants(seedTenants); setSelectedTenant(null) }} className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#9ba8b6]">Restablecer prueba</button></div></div>}

        {section === 'suscripciones' && <div className="mt-5 rounded-xl border border-white/8 bg-[#161d28] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-[#9ba8b6]">Los planes de prueba no afectan los planes reales ni las suscripciones operativas.</p><div className="flex gap-2"><button onClick={() => setEditor({ kind: 'plan' })} className="rounded-lg bg-[#00c896] px-3 py-2 text-xs font-semibold text-[#082e1e]">Nuevo plan</button><button onClick={() => setPlans(seedPlans)} className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#9ba8b6]">Restablecer prueba</button></div></div><div className="mt-4 grid gap-2 md:grid-cols-3">{plans.map(plan => <button key={plan.id} onClick={() => setEditor({ kind: 'plan', value: plan })} className="rounded-lg border border-white/8 bg-white/3 px-3 py-2 text-left text-xs text-[#9ba8b6] hover:bg-white/6"><span className="font-medium text-[#e8edf2]">Editar {plan.nombre}</span><span className="mt-0.5 block">{plan.limite}</span></button>)}</div></div>}

        {section === 'resumen' && <article className="mt-6 rounded-xl border border-white/8 bg-[#161d28] p-5"><p className="text-[11px] font-semibold uppercase tracking-[.08em] text-[#5f6f80]">Acciones rápidas</p><div className="mt-4 grid gap-2 sm:grid-cols-2 xl:grid-cols-3"><button onClick={() => setEditor({ kind: 'tenant' })} className="rounded-lg bg-[#00c896] px-3 py-3 text-left text-sm font-semibold text-[#082e1e]">+ Nuevo negocio</button><button onClick={() => setSection('suscripciones')} className="rounded-lg bg-white/4 px-3 py-3 text-left text-sm text-[#e8edf2]">↻ Nueva renovación</button><button onClick={() => setEditor({ kind: 'plan' })} className="rounded-lg bg-white/4 px-3 py-3 text-left text-sm text-[#e8edf2]">+ Crear plan</button><button onClick={() => setSection('alertas')} className="rounded-lg bg-white/4 px-3 py-3 text-left text-sm text-[#e8edf2]">🔔 Nueva alerta</button><button onClick={() => setSection('soporte')} className="rounded-lg bg-white/4 px-3 py-3 text-left text-sm text-[#e8edf2]">🎧 Ver soporte</button><button onClick={() => setSection('tenants')} className="rounded-lg bg-white/4 px-3 py-3 text-left text-sm text-[#e8edf2]">⌕ Buscar empresa</button></div></article>}

        {section === 'tenants' && selectedTenant && <article className="mt-5 rounded-xl border border-white/8 bg-[#161d28] p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[11px] font-semibold uppercase tracking-[.08em] text-[#5f6f80]">Ciclo de vida del negocio</p><h2 className="mt-1 font-semibold">{selectedTenant.nombre}</h2></div><Status>{selectedTenant.estado}</Status></div><div className="mt-4 flex flex-wrap items-center gap-2 text-xs">{['Trial', 'Activo', 'Por vencer', 'Vencido', 'Gracia', 'Suspendido', 'Cancelado', 'Archivado'].map((state, index) => <span key={state} className={`rounded-full px-2.5 py-1 ${selectedTenant.estado === state ? 'bg-[#00c896] font-semibold text-[#082e1e]' : 'bg-white/5 text-[#9ba8b6]'}`}>{index > 0 && <span className="mr-2 text-[#5f6f80]">→</span>}{state}</span>)}</div><div className="mt-5 flex flex-wrap gap-2"><button onClick={() => { setTenants(current => current.map(tenant => tenant.id === selectedTenant.id ? { ...tenant, estado: 'Suspendido', suspensionManual:true } : tenant)); setSelectedTenant(current => ({ ...current, estado: 'Suspendido', suspensionManual:true })) }} className="rounded-lg border border-amber-500/30 bg-amber-500/8 px-3 py-2 text-xs text-amber-300">Suspender manualmente</button><button onClick={() => { setTenants(current => current.map(tenant => tenant.id === selectedTenant.id ? { ...tenant, estado: 'Cancelado' } : tenant)); setSelectedTenant(current => ({ ...current, estado: 'Cancelado' })) }} className="rounded-lg border border-red-500/30 bg-red-500/8 px-3 py-2 text-xs text-red-300">Cancelar</button><button onClick={() => { setTenants(current => current.map(tenant => tenant.id === selectedTenant.id ? { ...tenant, estado: 'Archivado' } : tenant)); setSelectedTenant(current => ({ ...current, estado: 'Archivado' })) }} className="rounded-lg border border-white/8 px-3 py-2 text-xs text-[#9ba8b6]">Archivar</button><button disabled className="ml-auto rounded-lg border border-white/8 px-3 py-2 text-xs text-[#5f6f80] opacity-50" title="Solo configuración avanzada con doble confirmación y política de retención">Eliminar permanentemente · no disponible</button></div><p className="mt-3 text-xs text-[#5f6f80]">No existe borrado físico en el flujo normal. La eliminación definitiva requiere configuración avanzada, texto de confirmación, doble validación, auditoría y retención cumplida.</p></article>}

        {section === 'plan-management' && <PlanCapabilitiesManagement planes={capabilityPlans} negocios={tenants} onUpdatePlan={(id, changes) => setPlans(current => current.map(plan => plan.id === id ? { ...plan, ...changes, limite:formatPlanLimit({ ...plan, ...changes }) } : plan))} />}
        {section === 'landing-management' && <LandingManagement />}
        {section === 'accesos' && <RoleTemplatesManagement />}
        {section === 'accesos' && <article className="mt-5 rounded-xl border border-amber-500/25 bg-amber-500/5 p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[11px] font-semibold uppercase tracking-[.08em] text-amber-300">Regla de cupos del negocio</p><h2 className="mt-1 font-semibold text-[#e8edf2]">¿Quiénes consumen el límite de usuarios del plan?</h2></div><span className="rounded-full border border-amber-400/25 px-2.5 py-1 text-[11px] font-semibold text-amber-200">Backend pendiente</span></div><div className="mt-4 grid gap-3 md:grid-cols-2"><div className="rounded-lg border border-emerald-500/20 bg-emerald-500/5 p-3"><p className="text-xs font-semibold text-emerald-300">Sí consumen cupo</p><p className="mt-1 text-xs leading-relaxed text-[#9ba8b6]">Admin Owner activos, Admin Tenant activos y usuarios operativos activos creados por el Admin Tenant.</p></div><div className="rounded-lg border border-white/8 bg-[#0e1117]/50 p-3"><p className="text-xs font-semibold text-[#e8edf2]">No consumen cupo</p><p className="mt-1 text-xs leading-relaxed text-[#9ba8b6]">Administradores inactivos, usuarios operativos inactivos y SuperAdmins de la plataforma.</p></div></div><p className="mt-3 text-xs leading-relaxed text-amber-100">Al alcanzar el máximo contratado no se podrán activar ni crear más cuentas activas. Desactivar conserva el registro y su historial, pero libera el cupo. La validación autoritativa se aplicará al conectar el backend.</p></article>}
        {section === 'accesos' && <article className="mt-5 overflow-hidden rounded-xl border border-white/8 bg-[#161d28]"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-white/6 px-5 py-4"><div><h2 className="font-semibold">Sesiones por administrador</h2><p className="mt-1 text-xs text-[#5f6f80]">Consulta dispositivos y revoca accesos de esta demostración local.</p></div><select value={selectedAdminId || ''} onChange={event => setSelectedAdminId(event.target.value || null)} className="rounded-lg border border-white/8 bg-[#0e1117] px-3 py-2 text-xs text-[#e8edf2]"><option value="">Selecciona un administrador</option>{tenantAdmins.map(admin => <option key={admin.id} value={admin.id}>{admin.nombre} · {admin.tenant}</option>)}</select></div>{selectedAdminId ? <div className="divide-y divide-white/6">{adminSessions.filter(session => session.adminId === selectedAdminId).map(session => <div key={session.id} className="flex flex-wrap items-center gap-3 px-5 py-4"><MonitorSmartphone size={20} className="text-blue-300" /><div className="min-w-[200px] flex-1"><p className="text-sm font-medium text-[#e8edf2]">{session.dispositivo}</p><p className="text-xs text-[#5f6f80]">{session.ubicacion} · {session.ip} · {session.ultimoAcceso}</p></div><Status>{session.activa ? 'Activa' : 'Revocada'}</Status><button type="button" disabled={!session.activa} onClick={() => revokeSession(session)} className="rounded-lg border border-red-500/25 px-3 py-2 text-xs text-red-300 disabled:cursor-not-allowed disabled:opacity-40">Revocar sesión</button></div>)}{!adminSessions.some(session => session.adminId === selectedAdminId) && <p className="px-5 py-6 text-sm text-[#5f6f80]">Este administrador no tiene sesiones registradas.</p>}</div> : <p className="px-5 py-6 text-sm text-[#5f6f80]">Selecciona un administrador para consultar sus sesiones.</p>}</article>}
        <ModuleGuide route={route} />
        {editor && <DemoEditor key={`${editor.kind}-${editor.value?.id || 'new'}`} editor={editor} planOptions={plans} tenantOptions={tenants} records={{ tenants, plans, admins: tenantAdmins }} onClose={() => setEditor(null)} onSave={saveEditor} />}
        <ConfirmDialog action={pendingTransition} onCancel={() => setPendingTransition(null)} onConfirm={() => { if (pendingTransition.nextTenants) persistTenants(pendingTransition.nextTenants); if (pendingTransition.nextSelected) persistSelectedTenant(pendingTransition.nextSelected); setPendingTransition(null) }} />
      </section>
    </div>
  </main>
}

const queryClient = new QueryClient({ defaultOptions: { queries: { retry: 1, staleTime: 30_000 } } })
createRoot(document.getElementById('root')).render(<StrictMode><QueryClientProvider client={queryClient}><SuperAdminV2RefinedApp /></QueryClientProvider></StrictMode>)
